def set_expiration(message_func):
    def wrapper(*args, **kwargs):
        message = message_func(*args, **kwargs)
        message['expires_in'] = 24 * 60 * 60
        return message
    return wrapper

@set_expiration
def create_text_message(content):
    return {'type': 'text', 'content': content}

